using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CastellanReportsTests
{
    static readonly EntityId Site=new("site:kofu"),Head=new("person:shingen"),Agent=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start(bool employee=false){var s=new WorldSession(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],employee?Agent.Value:Head.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:CastleAdministration.Policy));var id=new EntityId("request:report-appointment");Good(s.ManageCastellan(new(id,CastellanAction.Appoint,Site,Agent),s.PlayerControl,s.Revision));return s;}
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long before=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>before);}}
    static EntityId Job(WorldSession s)=>s.DiagnosticSnapshot().Castellan!.Entries.First().Input.Id;
    static CastellanReportInput Input(WorldSession s,CastellanReportAction a=CastellanReportAction.Report,string? original=null)=>new(new("request:castellan-report/"+s.Revision),a,Job(s),original);
    static string Report(WorldSession s){Good(s.SendCastellanReport(Input(s),s.PlayerControl,s.Revision));return s.DiagnosticSnapshot().CastellanReports!.Papers.Last().Id;}
    static string FailAndKnow(WorldSession s,string id){s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,id));Advance(s,s.Seconds+2);var failure=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==id));Advance(s,s.Seconds+2);if(!MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,failure.Id,s.PlayerControl.Value))Good(s.Open(s.PlayerControl,new(failure.Id),s.Revision));return failure.Id;}
    [Fact]public void HeadCannotForgeTheAgentsObservation(){var s=Start();Assert.Equal(ResultCode.NotAvailable,s.SendCastellanReport(Input(s),Head,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().CastellanReports!.Papers);}
    [Fact]public void ReportIsOwnerSeparatedDatedAndDoesNotChangeStock(){var s=Start(true);var a=s.DiagnosticSnapshot();var id=Report(s);var p=s.CastellanReportsView()!.Reports.Single();Assert.Equal(id,p.Id);Assert.Equal(new EntityId("org:takeda"),p.Observation.Owner);Assert.Equal(a.ElapsedSeconds,p.Observation.ObservedAt);Assert.Equal(ContractJson.Write(a.Communities),ContractJson.Write(s.DiagnosticSnapshot().Communities));}
    [Fact]public void NpcReportDoesNotLeakBeforeDeliveryOrOpening(){var s=Start();Advance(s,86400);Assert.Empty(s.CastellanReportsView()!.Reports);var p=s.DiagnosticSnapshot().CastellanReports!.Papers.Single();Assert.Equal(Agent,p.Sender);Assert.Equal(86400,p.Observation.ObservedAt);Advance(s,86402);Assert.Empty(s.CastellanReportsView()!.Reports);Good(s.Open(Head,new(p.Id),s.Revision));Assert.Single(s.CastellanReportsView()!.Reports);}
    [Fact]public void UnknownFailureCannotAuthorizeResend(){var s=Start(true);var p=Report(s);Assert.Equal(ResultCode.NotAvailable,s.SendCastellanReport(Input(s,CastellanReportAction.Resend,p),Agent,s.Revision).Code);}
    [Fact]public void KnownFailureResendsOriginalObservationNotCurrentStock(){var s=Start(true);var p=Report(s);FailAndKnow(s,p);Good(s.ManageCommunity(new(new("request:report-stock-change"),Site,EconomyAction.RelieveVillage,10),Agent,s.Revision));Good(s.SendCastellanReport(Input(s,CastellanReportAction.Resend,p),Agent,s.Revision));var reports=s.DiagnosticSnapshot().CastellanReports!.Papers;Assert.Equal(reports[0].Observation,reports[1].Observation);Assert.Equal(p,reports[1].Original);Assert.NotEqual(s.CommunityEconomyView()!.Accounts.HouseRice,reports[1].Observation.Rice);}
    [Fact]public void CopiesAreBoundedWithoutRepeatingAnyConsumption(){var s=Start(true);var p=Report(s);FailAndKnow(s,p);Good(s.SendCastellanReport(Input(s,CastellanReportAction.Resend,p),Agent,s.Revision));Good(s.SendCastellanReport(Input(s,CastellanReportAction.Resend,p),Agent,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.SendCastellanReport(Input(s,CastellanReportAction.Resend,p),Agent,s.Revision).Code);Assert.Equal(3,s.DiagnosticSnapshot().CastellanReports!.Papers.Length);Assert.Equal(3000,s.CommunityEconomyView()!.Accounts.HouseRice);}
    [Fact]public void DuplicateReportDoesNotCreateAnotherCourier(){var s=Start(true);var i=Input(s);Good(s.SendCastellanReport(i,Agent,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.SendCastellanReport(i,Agent,0).Code);Assert.Single(s.DiagnosticSnapshot().CastellanReports!.Papers);Assert.Equal(ResultCode.IdPayloadConflict,s.SendCastellanReport(i with{Action=CastellanReportAction.Resend},Agent,s.Revision).Code);}
    [Fact]public void StaleReportCannotObserveNewStock(){var s=Start(true);var i=Input(s);Report(s);Assert.Equal(ResultCode.StateChanged,s.SendCastellanReport(i with{Id=new("request:stale-report")},Agent,0).Code);}
    [Fact]public void ForgedObservationRejectedOnLoad(){var s=Start(true);Report(s);var w=s.DiagnosticSnapshot();var ps=w.CastellanReports!.Papers.ToArray();ps[0]=ps[0] with{Observation=ps[0].Observation with{Rice=9999}};w.CastellanReports=w.CastellanReports with{Papers=ps};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void EarlierLetterSurvivesLaterReappointment(){var s=Start(true);var p=Report(s);Good(s.ManageCastellan(new(new("request:report-new-office"),CastellanAction.Appoint,Site,Agent),Agent,s.Revision));Assert.Equal(Job(s),s.DiagnosticSnapshot().CastellanReports!.Papers.Single(x=>x.Id==p).Appointment);new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ActualGenerationReportDeliveryOpeningAndFailureRecovery(int phase){var a=Start(phase is 0 or 3);if(phase is 0 or 3){var p=Report(a);if(phase==3)FailAndKnow(a,p);}else {Advance(a,86400);if(phase==2){var p=a.DiagnosticSnapshot().CastellanReports!.Papers.Single();Advance(a,86402);Good(a.Open(Head,new(p.Id),a.Revision));}}a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"castellan-report-save-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"report",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("report"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.CastellanReportsView()),ContractJson.Write(b.CastellanReportsView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,"castellan-report-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"castellan-report-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var q in new[]{a,b})Advance(q,q.Seconds+10);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.CastellanReportsView()),ContractJson.Write(b.CastellanReportsView()));}
    [Fact]public void FailureLearnedLaterCannotJustifyABackdatedResend(){var s=Start(true);var id=Report(s);FailAndKnow(s,id);Good(s.SendCastellanReport(Input(s,CastellanReportAction.Resend,id),Agent,s.Revision));var w=s.DiagnosticSnapshot();var es=w.CastellanReports!.Entries.ToArray();var ps=w.CastellanReports.Papers.ToArray();es[^1]=es[^1] with{At=0};ps[^1]=ps[^1] with{At=0};w.CastellanReports=w.CastellanReports with{Entries=es,Papers=ps};w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==ps[^1].Id?m with{CreatedAt=0}:m).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ReservedAutoReportIdDoesNotCrashLaterNpcAdministration(){var s=Start();var root=new EntityId("request:castellan-auto/"+ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes("decision:npc-community/site/kofu/d1")));Good(s.ManageCommunity(new(root,Site,EconomyAction.RelieveVillage,1),Head,s.Revision));Advance(s,86400);var report=s.DiagnosticSnapshot().CastellanReports!.Papers.Single();Assert.NotEqual(root,report.Request);Assert.StartsWith(root.Value+"/n",report.Request.Value);new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}

    [Fact]public void TravellingNpcCannotSendAnOmniscientLocalStoreReport(){var s=Start();Good(s.ManageHouseFreight(new HouseFreightInput(new("request:castellan-away-freight"),HouseFreightAction.Dispatch,Home:Site,Source:new("site:sakai"),Commodity:"wood",Quantity:10,Advance:200){Carrier=Agent},Head,s.Revision));Advance(s,86400);Assert.Contains(s.DiagnosticSnapshot().Branches!.Journeys,j=>j.Actor==Agent&&j.Legs.Last().EndAt>86400);Assert.Empty(s.DiagnosticSnapshot().CastellanReports!.Papers);new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}

    [Theory][InlineData(false)][InlineData(true)]public void RestingCannotPerformFreshReportOrResend(bool resend){var s=Start(true);string? original=null;if(resend){original=Report(s);FailAndKnow(s,original);}Good(s.ManageLife(new(new("request:report-rest"),LifeAction.RestOutside,Site),Agent,s.Revision));var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.SendCastellanReport(Input(s,resend?CastellanReportAction.Resend:CastellanReportAction.Report,original),Agent,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void MissingNpcReportCannotBeAcceptedAsAValidSave(){var s=Start();Advance(s,86400);var w=s.DiagnosticSnapshot();Assert.Single(w.CastellanReports!.Papers);w.CastellanReports=w.CastellanReports with{Papers=[]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}

}
